			break;
		case 5:
			allowedDirectionsSlot5[dir.ordinal()] = enabled;
			break;
		case 6:
			allowedDirectionsOrb[dir.ordinal()] = enabled;
			break;
		case 7:
			allowedDirectionsOutput[dir.ordinal()] = enabled;
			break;
		}
	}

	@Override
